--
-- Name: access_level(text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.access_level(p_user_id text, p_project_id text, p_entity text, p_action text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  lvl int := 0;
  resource_name text;
  action_name text;
BEGIN
  IF p_user_id IS NULL THEN RETURN 0; END IF;

  action_name := CASE p_action
    WHEN 'readF' THEN 'get'
    WHEN 'createF' THEN 'create'
    WHEN 'updateF' THEN 'update'
    WHEN 'deleteF' THEN 'delete'
    ELSE lower(p_action)
  END;
  resource_name := lower(p_entity) || '.' || action_name;

  SELECT COALESCE(MAX(CASE WHEN p.allowed = 1 THEN 9 ELSE 0 END), 0)
    INTO lvl
  FROM user_roles ur
  JOIN permissions p ON p."roleId" = ur."roleId"
  WHERE ur."userId" = p_user_id
    AND p."resourceName" = resource_name;

  RETURN lvl;
END;
$$;


--
-- Name: accessible_projects_for_issue_read(); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.accessible_projects_for_issue_read() RETURNS TABLE(project_id text, read_level integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT m."projectId", MAX(CASE WHEN p.allowed = 1 THEN 9 ELSE 0 END)
  FROM memberships m
  JOIN user_roles ur ON ur."userId" = m."userId"
  JOIN permissions p ON p."roleId" = ur."roleId"
  WHERE m."userId" = '7ea8b586623c-5e99-bfcb-d51d01a7a16b'
    AND p."resourceName" = 'issue.get'
  GROUP BY m."projectId";
$$;


--
-- Name: can_access_issue(text, text, text, text, text); Type: FUNCTION; Schema: auth; Owner: -
--

CREATE FUNCTION auth.can_access_issue(p_issue_id text, p_project_id text, p_assignee text, p_created_user text, p_action text DEFAULT 'readF'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  uid text := '7ea8b586623c-5e99-bfcb-d51d01a7a16b';
  lvl int;
BEGIN
  IF uid IS NULL THEN RETURN false; END IF;

  lvl := auth.access_level(uid, p_project_id, 'Issue', p_action);

  IF lvl = 9 THEN RETURN true; END IF;
  IF lvl = 0 THEN RETURN false; END IF;
  IF lvl = 1 THEN RETURN p_assignee = uid; END IF;   -- Developer: assigned only
  IF lvl >= 2 THEN RETURN true; END IF;              -- PM: all issues in project

  RETURN false;
END;
$$;


