--
-- Name: add_last_activity_date_fn(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_last_activity_date_fn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
                BEGIN
                    BEGIN
                                IF NEW."relatedTo" = 'issue' THEN
                                UPDATE issues SET "lastActivityDate" = NEW."dateCreated" where id = NEW."relatedId";
                                ELSIF NEW."relatedTo" = 'project' THEN
                                UPDATE memberships SET "lastActivityDate" = NEW."dateCreated" where "projectId" = NEW."relatedId" AND "userId" = NEW."createdUser";
                                END IF;
                            END;
RETURN NULL;
                END;
                $$;


