--
-- Name: user_activities; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_activities AS
 SELECT "Activity".id,
    "User".id AS "userId",
    "User".name AS "createdUserName",
    "Activity"."relatedTo",
    "Activity"."relatedId",
    "Activity".type,
    "Activity"."dateCreated",
    "Activity"."relatedActivity",
    "Activity"."relatedActivityId",
    "Activity"."relatedActivityModule",
    "Issue"."projectId",
    "Issue"."issueNumber"
   FROM ((public.users "User"
     LEFT JOIN public.activities "Activity" ON ((("Activity"."createdUser")::text = (public.getmodelid())::text)))
     LEFT JOIN public.issues "Issue" ON (((("Issue".id)::text = ("Activity"."relatedId")::text) AND (("Activity"."relatedTo")::text = 'issue'::text) AND (("Issue"."createdUser")::text = (public.getmodelid())::text))))
  WHERE (("User".id)::text = (public.getmodelid())::text)
  ORDER BY "Activity"."dateCreated" DESC
 LIMIT 5;


--
-- Name: user_collaborations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_collaborations AS
 SELECT min(((public.uuid_generate_v4())::character varying)::text) AS id,
    (floor((power((count("Comment".id))::numeric, 0.5) * (13)::numeric)))::double precision AS collaboration,
    "User".id AS "userId"
   FROM (public.comments "Comment"
     LEFT JOIN public.users "User" ON ((("User".id)::text = ("Comment"."createdUser")::text)))
  WHERE ((timezone('UTC'::text, now()))::date = ("Comment"."dateCreated")::date)
  GROUP BY "User".id;


--
-- Name: user_collaborations_test; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_collaborations_test AS
 SELECT (public.uuid_generate_v4())::character varying AS id,
    floor((power((count("Comment".id))::numeric, 0.5) * (13)::numeric)) AS collaboration,
    "User".id AS "userId"
   FROM (public.comments "Comment"
     LEFT JOIN public.users "User" ON ((("User".id)::text = ("Comment"."createdUser")::text)))
  WHERE ((timezone('UTC'::text, now()))::date = ("Comment"."dateCreated")::date)
  GROUP BY "User".id;


--
-- Name: user_collaborations_test3; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_collaborations_test3 AS
 SELECT (public.uuid_generate_v4())::character varying AS id,
    floor((power((count("Comment".id))::double precision, '0.5'::double precision) * (13)::double precision)) AS collaboration,
    "User".id AS "userId"
   FROM (public.comments "Comment"
     LEFT JOIN public.users "User" ON ((("User".id)::text = ("Comment"."createdUser")::text)))
  WHERE ((timezone('UTC'::text, now()))::date = ("Comment"."dateCreated")::date)
  GROUP BY "User".id;


