    "modifiedUserName" character varying(50) NOT NULL
);


--
-- Name: user_group_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_group_permissions AS
 SELECT min(("Permission".id)::text) AS id,
    "Membership"."projectId" AS "relatedId",
    'project'::character varying(36) AS "groupName",
    "Permission"."resourceName" AS entity,
    max("Permission".allowed) AS allowed
   FROM ((public.permissions "Permission"
     JOIN public.user_roles "UserRole" ON ((("UserRole"."roleId")::text = ("Permission"."roleId")::text)))
     JOIN public.memberships "Membership" ON (((("Membership"."userId")::text = ("UserRole"."userId")::text) AND (("Membership"."userId")::text = (public.getcurrentuserid())::text) AND (("Membership"."projectId")::text = (public.getmodelid())::text))))
  WHERE ("Permission"."resourceName" IS NOT NULL)
  GROUP BY "Membership"."projectId", "Permission"."resourceName";


--
-- Name: user_latest_issues; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_latest_issues AS
 SELECT "Issue".id,
    "Issue".subject,
    "Issue"."issueNumber",
    "Issue".status,
    "Issue"."lastActivityDate",
    "Issue"."createdUser" AS "userId",
    "Issue"."projectId",
    "Project"."shortCode" AS "projectShortCode"
   FROM (public.issues "Issue"
     LEFT JOIN public.projects "Project" ON ((("Issue"."projectId")::text = ("Project".id)::text)))
  WHERE (("Issue"."createdUser")::text = (public.getmodelid())::text)
  GROUP BY "Issue".id, "Issue".subject, "Issue"."issueNumber", "Issue".status, "Issue"."lastActivityDate", "Issue"."createdUser", "Issue"."projectId", "Project"."shortCode"
  ORDER BY "Issue"."lastActivityDate" DESC
 LIMIT 5;


--
-- Name: user_latest_projects; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_latest_projects AS
 SELECT "Membership"."userId",
    "Project".id,
    "Project".name,
    "Project".description,
    "Project".status,
    "Membership"."lastActivityDate",
    "Project"."shortCode",
    ( SELECT count("Issue".id) AS count
           FROM public.issues "Issue"
          WHERE (("Issue"."projectId")::text = ("Project".id)::text)) AS "totalIssues",
    ( SELECT count("Issue".id) AS count
           FROM (public.issues "Issue"
             LEFT JOIN public.issue_statuses "IssueStatus" ON ((("IssueStatus".id)::text = ("Issue"."statusId")::text)))
          WHERE ((("Issue"."projectId")::text = ("Project".id)::text) AND ("IssueStatus".done = '1'::smallint))) AS "closedIssues"
   FROM (public.projects "Project"
     JOIN public.memberships "Membership" ON (((("Membership"."projectId")::text = ("Project".id)::text) AND (("Membership"."userId")::text = (public.getmodelid())::text))))
  WHERE (("Membership"."createdUser")::text = (public.getmodelid())::text)
  GROUP BY "Project".id, "Project".name, "Project".description, "Project".status, "Project"."shortCode", "Membership"."userId", "Membership"."lastActivityDate"
  ORDER BY "Membership"."lastActivityDate" DESC
 LIMIT 5;


--
-- Name: user_open_closed_issues; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_open_closed_issues AS
 SELECT sum(
        CASE
            WHEN ("IssueStatuses".done = '0'::smallint) THEN 1
            ELSE 0
        END) AS "openIssues",
    sum(
        CASE
            WHEN ("IssueStatuses".done = '1'::smallint) THEN 1
            ELSE 0
        END) AS "closedIssues",
    min(((public.uuid_generate_v4())::character varying)::text) AS id,
    "User".id AS "userId"
   FROM ((public.issues "Issue"
     LEFT JOIN public.users "User" ON ((("User".id)::text = ("Issue"."createdUser")::text)))
     LEFT JOIN public.issue_statuses "IssueStatuses" ON ((("IssueStatuses".id)::text = ("Issue"."statusId")::text)))
  GROUP BY "User".id;


--
-- Name: user_open_closed_projects; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_open_closed_projects AS
 SELECT min(((public.uuid_generate_v4())::character varying)::text) AS id,
    sum(
        CASE
            WHEN ("Project".done = '0'::smallint) THEN 1
            ELSE 0
        END) AS "openProjects",
    sum(
        CASE
            WHEN ("Project".done = '1'::smallint) THEN 1
            ELSE 0
        END) AS "closedProjects",
    "Membership"."userId"
   FROM (public.projects "Project"
     JOIN public.memberships "Membership" ON ((("Membership"."projectId")::text = ("Project".id)::text)))
  GROUP BY "Membership"."userId";


--
-- Name: user_permissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_permissions AS
 SELECT min(("Permission".id)::text) AS id,
    "UserRole"."userId",
    "Permission"."resourceName" AS entity,
    max("Permission".allowed) AS allowed
   FROM (public.permissions "Permission"
     JOIN public.user_roles "UserRole" ON (((("UserRole"."roleId")::text = ("Permission"."roleId")::text) AND (("UserRole"."userId")::text = (public.getmodelid())::text))))
  WHERE ("Permission"."resourceName" IS NOT NULL)
  GROUP BY "UserRole"."userId", "Permission"."resourceName";


