--
-- Name: user_time_spent; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_time_spent AS
 SELECT min(((public.uuid_generate_v4())::character varying)::text) AS id,
    sum((((("Timelog".days * 8) * 60) + ("Timelog".hours * 60)) + "Timelog".minutes)) AS "totalMinutes",
    "User".id AS "userId"
   FROM ((public.users "User"
     JOIN public.issues "Issue" ON ((("User".id)::text = ("Issue"."createdUser")::text)))
     JOIN public.time_logs "Timelog" ON ((("Timelog"."issueId")::text = ("Issue".id)::text)))
  WHERE ("Timelog".deleted = '0'::smallint)
  GROUP BY "User".id;


--
-- Name: user_works_most_with; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_works_most_with AS
 SELECT "Membership1"."userId",
    "Membership2"."userId" AS id,
    "User".name,
    "User".title,
    count("Membership2".id) AS "occurenceOfUser"
   FROM (((public.projects "Project"
     LEFT JOIN public.memberships "Membership1" ON ((("Membership1"."projectId")::text = ("Project".id)::text)))
     LEFT JOIN public.memberships "Membership2" ON (((("Membership2"."projectId")::text = ("Membership1"."projectId")::text) AND (("Membership2"."userId")::text <> (public.getmodelid())::text))))
     LEFT JOIN public.users "User" ON ((("User".id)::text = ("Membership2"."userId")::text)))
  WHERE (("Membership1"."userId")::text = (public.getmodelid())::text)
  GROUP BY "Membership1"."userId", "Membership2"."userId", "User".name, "User".title
  ORDER BY (count("Membership2".id)) DESC
 LIMIT 3;


